/**
 * diagnosis/path-dependency.ts — 路径依赖检测
 *
 * 识别哪些缝隙维度长期不变化，是否显著偏离同类团队的正常变化频率。
 *
 * 依赖：gap-dynamics.stickyDimensions 提供候选列表。
 *
 * 同类团队基线来源：
 *   1. 85 个框架库中编码的规则（如"运营效率型组织通常每 30-60 天调整信息流"）
 *   2. 群像蒸馏积累的同类角色对照数据
 *   3. 初期基线不完整时，peerAvgChangeRate = null，不做异常判定
 *
 * 当前成熟度：可计算 stickinessScore 和 monthsUnchanged。
 * peer 基线等数据飞轮积累。
 */
import type { PathDependency } from './types';
/**
 * Detect path dependencies from sticky dimensions.
 * Compares against peer baselines where available.
 *
 * @param teamId - The team to analyze
 * @returns Array of path dependencies (may be empty)
 */
export declare function detectPathDependency(teamId: string): PathDependency[];
